-- ---------------------------------------------------------------------
-- Baralho do Perfil: cartas aprovadas, com dicas e respostas aceitas.
--
-- Gerado por api/bin/exportar-cartas.php. Nao edite na mao: gere cartas
-- no painel /admin, aprove as boas e rode o script de novo.
--
-- O container importa este arquivo na primeira subida, logo depois do
-- database.sql. Rodar de novo nao duplica nada: cada carta e apagada
-- pelo qid antes de ser inserida.
-- Cartas neste arquivo: 21
-- ---------------------------------------------------------------------

SET NAMES utf8mb4;

