INSERT INTO `cartas` (`categoria_id`, `qid`, `resposta`, `resposta_normalizada`, `url_fonte`, `resumo_fonte`, `status`) SELECT `id`, 'Q189', 'Islândia', 'islandia', 'https://pt.wikipedia.org/wiki/Isl%C3%A2ndia', 'Islândia ) é um país nórdico insular europeu situado no oceano Atlântico Norte. O seu território abrange a ilha homônima e algumas pequenas ilhas no oceano Atlântico, localizadas entre a Europa continental e a Groenlândia. O país tem uma população de 390 mil habitantes em uma área de cerca de 103 mil quilômetros quadrados. A sua capital e maior cidade é Reiquiavique, cuja área metropolitana abriga cerca de dois terços da população nacional. Devido à sua localização na dorsal mesoatlântica, a Islândia tem uma grande atividade vulcânica e um importante gradiente geotérmico, o que afeta muito a sua paisagem. O interior é constituído principalmente por um planalto caracterizado por campos de areia, montanhas e geleiras. Aquecida pela corrente do Golfo, a Islândia tem um clima temperado em relação à sua latitude e oferece um ambiente habitável.', 'aprovada' FROM `categorias` WHERE `chave` = 'lugar';
