INSERT INTO `cartas` (`categoria_id`, `qid`, `resposta`, `resposta_normalizada`, `url_fonte`, `resumo_fonte`, `status`) SELECT `id`, 'Q656', 'São Petersburgo', 'sao petersburgo', 'https://pt.wikipedia.org/wiki/S%C3%A3o_Petersburgo', 'São Petersburgo ou Sampetersburgo é a segunda maior cidade da Rússia, politicamente incorporada como uma cidade autônoma. Ela está localizada ao longo do rio Neva, na entrada do Golfo da Finlândia, no Mar Báltico. Em 1914, o nome da cidade foi mudado para Petrogrado e, em 1924, para Leningrado. Em 1991, após o colapso da União Soviética, a cidade voltou ao seu nome original. É frequentemente chamada apenas de Petersburgo e informalmente conhecida como Peter.', 'aprovada' FROM `categorias` WHERE `chave` = 'lugar';
